import numpy as np
import pytest
from src.log_field_3d import TorusLogField,spectral_configuration
from src.extend_log_field_3c import merge_retained_sharp_modes


def deterministic_field(n,regularization='sharp'):
    spectrum,covariance,variance=spectral_configuration(n,regularization=regularization)
    # Deterministic evenreal coefficients test Hermitian bookkeeping only;
    # no Gaussian sample orN64field is generated by this test.
    k=np.rint(np.fft.fftfreq(n)*n)
    coefficients=np.sqrt(spectrum)*(1+.2*np.cos(2*np.pi*k[:,None,None]/n))
    h=np.fft.ifftn(coefficients*n**3).real
    return TorusLogField(h,variance,covariance,spectrum,{'regularization':regularization,'cutoff_fraction':1/3})


def test_retained_modes_new_high_modes_reality_andvariance():
    old,new=deterministic_field(8),deterministic_field(12)
    merged=merge_retained_sharp_modes(old,new)
    k=np.rint(np.fft.fftfreq(8)*8).astype(int);active=old.spectrum>0
    i,j,ell=np.nonzero(active);dest=(k[i]%12,k[j]%12,k[ell]%12)
    coefficients=np.fft.fftn(merged.h)/12**3
    old_c=np.fft.fftn(old.h)/8**3;new_c=np.fft.fftn(new.h)/12**3
    np.testing.assert_allclose(coefficients[dest],old_c[active],atol=5e-16,rtol=2e-14)
    untouched=np.ones((12,)*3,dtype=bool);untouched[dest]=False
    np.testing.assert_allclose(coefficients[untouched],new_c[untouched],atol=5e-16,rtol=2e-14)
    assert np.isrealobj(merged.h)and abs(merged.h.mean())<2e-15
    assert merged.metadata['imaginary_roundoff_max']<2e-15
    assert merged.variance==pytest.approx(merged.spectrum.sum(),abs=1e-15)
    np.testing.assert_array_equal(merged.spectrum,new.spectrum)


def test_heat_and_nonextension_are_rejected():
    with pytest.raises(ValueError,match='sharp'):
        merge_retained_sharp_modes(deterministic_field(8,'heat'),deterministic_field(12))
    with pytest.raises(ValueError,match='larger'):
        merge_retained_sharp_modes(deterministic_field(8),deterministic_field(8))
